// Checks that the webhook came from your Crystalline instance.
// Needs NODE_FUNCTION_ALLOW_BUILTIN=crypto and the secret in
// CRYSTALLINE_WEBHOOK_SECRET (with N8N_BLOCK_ENV_ACCESS_IN_NODE=false), the
// same value as the instance's automation.webhook.secret.
const crypto = require('crypto');
const secret = $env.CRYSTALLINE_WEBHOOK_SECRET;
if (!secret) {
  throw new Error('Set CRYSTALLINE_WEBHOOK_SECRET in the n8n environment.');
}
const headers = $input.first().json.headers || {};
const timestamp = String(headers['x-crystalline-timestamp'] || '');
const signature = String(headers['x-crystalline-signature'] || '');
// Refuse a replay: the timestamp is unix seconds and is part of what is signed.
const age = Math.abs(Date.now() / 1000 - Number(timestamp));
if (!timestamp || !(age <= 300)) {
  throw new Error('The webhook has no timestamp or is older than 5 minutes.');
}
// The signature covers the raw body bytes, so the Webhook node keeps them
// (option Raw Body) in the binary property data.
const body = await this.helpers.getBinaryDataBuffer(0, 'data');
const expected = 'sha256=' + crypto.createHmac('sha256', secret)
  .update(timestamp + '.')
  .update(body)
  .digest('hex');
const given = Buffer.from(signature);
const wanted = Buffer.from(expected);
if (given.length !== wanted.length || !crypto.timingSafeEqual(given, wanted)) {
  throw new Error('The webhook signature does not match.');
}
const event = JSON.parse(body.toString('utf8'));
if (event.event !== 'reflect') {
  return [];
}
return [{ json: { event: event.event, domain: event.domain, counts: event.counts } }];

// Edit these values. The token is not here: it is the credential
// "Crystalline runner token" (Bearer Auth) on the HTTP Request nodes and on
// the MCP Client Tool.
return [{
  json: {
    // The server's address as n8n reaches it, without a trailing slash. A
    // host name the server does not know must be in its
    // CRYSTALLINE_SERVICE_ALLOWED_HOSTS.
    url: 'https://crystalline.example.com',
    // The domain this workflow works.
    domain: 'eng',
    // The item cap. Use the same number as in the prompt you pasted.
    maxItems: 10,
    // The runner label the run record shows.
    runner: 'n8n',
    startedAt: new Date().toISOString(),
  },
}];

// What renew-lease.json needs to renew this run's lease.
const settings = $('Settings').first().json;
return [{
  json: {
    url: settings.url,
    domain: settings.domain,
    loop: 'reflect',
    token: $('Take the lease').first().json.data.token,
  },
}];

// Reads the summary block the agent ends with (Done, Left for a person,
// Errors) into the run record, the way crystalline reflect run does.
const settings = $('Settings').first().json;
const token = $('Take the lease').first().json.data.token;
const answer = $input.first().json;
const text = typeof answer.output === 'string' ? answer.output : '';
const lines = text.split('\n').map((line) =>
  line.trim().replace(/[*_]/g, '').replace(/^[-+] /, '').trim());
const count = (line, key) => {
  const m = line.match(new RegExp('^' + key + '\\s*:\\s*(\\d+)', 'i'));
  return m ? Number(m[1]) : null;
};
const next = (from) => {
  let i = from;
  while (i < lines.length && (lines[i] === '' || lines[i].startsWith('```'))) i++;
  return i;
};
let parsed = null;
for (let i = lines.length - 1; i >= 0 && !parsed; i--) {
  const done = count(lines[i], 'Done');
  if (done === null) continue;
  const l = next(i + 1);
  const left = l < lines.length ? count(lines[l], 'Left for a person') : null;
  if (left === null) continue;
  const e = next(l + 1);
  const errors = e < lines.length ? count(lines[e], 'Errors') : null;
  if (errors === null) continue;
  const rest = lines.slice(e + 1).filter((line) => !line.startsWith('```')).join('\n').trim();
  parsed = { done, left, errors, rest };
}
let outcome = 'failed';
let summary = 'The agent ended without a summary block.';
let done = 0;
if (answer.error) {
  summary = 'The agent could not run: ' + JSON.stringify(answer.error).slice(0, 500);
} else if (parsed) {
  done = parsed.done;
  outcome = parsed.done >= settings.maxItems ? 'stopped_at_cap' : 'done';
  summary = `Done: ${parsed.done}. Left for a person: ${parsed.left}. Errors: ${parsed.errors}.`;
  if (parsed.rest) summary += '\n\n' + parsed.rest;
}
return [{ json: { domain: settings.domain, token, outcome, done, summary, agentEnded: !answer.error } }];
